import{_ as e,o as t,c as i,ag as l}from"./chunks/framework.D9ghT4bC.js";const o="/Unciv/assets/%E5%9B%BE%E7%89%871.e98WXxdY.jpg",s="/Unciv/assets/%E5%9B%BE%E7%89%872.nKD_OYga.jpg",n="/Unciv/assets/%E5%9B%BE%E7%89%873.BnbXdrEk.jpg",b=JSON.parse('{"title":"文明积分计算","description":"","frontmatter":{"title":"文明积分计算"},"headers":[],"relativePath":"zh/Community/Code-analysis/Score-calculation/index.md","filePath":"zh/Community/Code-analysis/Score-calculation/index.md"}'),r={name:"zh/Community/Code-analysis/Score-calculation/index.md"};function c(p,a,d,h,u,m){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="文明积分计算" tabindex="-1">文明积分计算 <a class="header-anchor" href="#文明积分计算" aria-label="Permalink to &quot;文明积分计算&quot;">​</a></h1><blockquote><p>作者：华花</p><p>版本：4.19.12</p><p>日期：2026/2/14</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>文明积分作为报表的第一元素，通常很受萌新们的重视，而有经验的玩家都认同它实际上毫无意义。</p><h2 id="一-按地图大小计算分数折算比" tabindex="-1">一：按地图大小计算分数折算比 <a class="header-anchor" href="#一-按地图大小计算分数折算比" aria-label="Permalink to &quot;一：按地图大小计算分数折算比&quot;">​</a></h2><p>以中图1276格为标准（C5标图则以80*52=4160格），t=1276/开的图总地块数；如果t&gt;1，t=1+(t-1)/3。</p><h2 id="二-分别计算各类分数" tabindex="-1">二：分别计算各类分数 <a class="header-anchor" href="#二-分别计算各类分数" aria-label="Permalink to &quot;二：分别计算各类分数&quot;">​</a></h2><ul><li>城市分 = 城市总数 × 10 × t</li><li>人口分 = 人口总数 × 3 × t</li><li>地块分 = 圈到的非水域地块数（水域指浅海/海洋，不包括湖泊）× 1 × t</li><li>奇观分 = 拥有世界奇观总数 × 20</li><li>科技分 = 已研究科技数 × 4</li><li>未来科技分 = 已研究未来科技次数 × 10</li></ul><h2 id="三-加和所有分数-得到文明积分" tabindex="-1">三：加和所有分数，得到文明积分 <a class="header-anchor" href="#三-加和所有分数-得到文明积分" aria-label="Permalink to &quot;三：加和所有分数，得到文明积分&quot;">​</a></h2><p>将上述各项分数相加，即得到最终的文明积分。</p><h2 id="四-举例计算" tabindex="-1">四：举例计算 <a class="header-anchor" href="#四-举例计算" aria-label="Permalink to &quot;四：举例计算&quot;">​</a></h2><p>我们来举一个实例看看公式是否正确：</p><p><img src="'+o+'" alt=""><img src="'+s+'" alt=""></p><p>这张图是大图（66×43=2838，t=0.4496），我们是荷兰，9城65人口；地块有2片海，领土是102；建了3奇观；研究了20个科技。那么分数是：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0.4496 × (90 + 195 + 102) + 120 + 80 = 373.99</span></span></code></pre></div><p>恰好对应374分。</p><h2 id="五-小贴士" tabindex="-1">五：小贴士 <a class="header-anchor" href="#五-小贴士" aria-label="Permalink to &quot;五：小贴士&quot;">​</a></h2><ul><li>更小的地图在相同发育下具有更高的分数，更大的地图则相反。</li><li>由于常规对局中不会多次研究未来科技，因此文明积分可以由报表中的数据及政治栏目中的奇观数量近似计算，这也意味着文明积分不具有战术上的意义。</li><li>常规对局中文明积分通常随着城市、人口和自然扩地、研发科技数缓慢上涨，突然的跃升可能是由于建立/攻占/联姻城市，建成多个奇观或尾盘烧大科过大量科技。</li><li>文明积分能够一定程度上反映文明长期实力，相比报表中其他数据（如产能、金钱等）很难在短期内剧烈变动。但对局中更多关注短期数据（如军评、重要文化节点）以判断局势和做出决策。</li></ul><h2 id="六-代码参考" tabindex="-1">六：代码参考 <a class="header-anchor" href="#六-代码参考" aria-label="Permalink to &quot;六：代码参考&quot;">​</a></h2><p><code>core\\src\\com\\unciv\\logic\\civilization\\Civlization</code></p><p>（注：现版本中代码已将具体分数折算比例交由规则集定义，需结合G&amp;K代码阅读具体数值）</p><p><img src="'+n+'" alt=""></p>',22)])])}const x=e(r,[["render",c]]);export{b as __pageData,x as default};
